function openBookChapter(chNum, pageNum){
  const ch = BONBOOK_CHAPTERS.find(c => c.num === chNum);
  if(!ch) return;
  _bookCurrentChNum = ch.num;
  const pdfUrl = pageNum ? ch.file + '#page=' + pageNum : ch.file;
  const titleEl = document.getElementById('bookReaderTitle');
  const link = document.getElementById('bookReaderOpenLink');
  const iframe = document.getElementById('bookReaderIframe');
  if(titleEl) titleEl.textContent = 'Ch.' + ch.num + ' — ' + ch.title;
  if(link)    { link.href = pdfUrl; link.textContent = 'Open ↗'; }
  if(iframe)  {
    // Set iframe height to fill remaining viewport
    iframe.style.height = (window.innerHeight - 54) + 'px';
    iframe.src = pdfUrl;
  }
  _updateBookNavBtns();
  navTo('book-reader');
}

let _bookCurrentChNum = null;

function navigateBookChapter(dir){
  if(!_bookCurrentChNum) return;
  const newNum = _bookCurrentChNum + dir;
  const ch = BONBOOK_CHAPTERS.find(c => c.num === newNum);
  if(ch) openBookChapter(ch.num);
}

function _updateBookNavBtns(){
  const prevBtn = document.getElementById('bookReaderPrevBtn');
  const nextBtn = document.getElementById('bookReaderNextBtn');
  const label   = document.getElementById('bookReaderChLabel');
  if(prevBtn) prevBtn.disabled = !_bookCurrentChNum || _bookCurrentChNum <= 1;
  if(nextBtn) nextBtn.disabled = !_bookCurrentChNum || _bookCurrentChNum >= BONBOOK_CHAPTERS.length;
  if(label && _bookCurrentChNum) label.textContent = _bookCurrentChNum + ' / ' + BONBOOK_CHAPTERS.length;
}

let _activePageId = 'home';
function navTo(id){
  // Close any open modals
  const flashcardModal = document.getElementById('flashcardModal');
  if(flashcardModal) flashcardModal.classList.remove('show');

  // Only touch the two pages that change — avoid iterating all pages
  if(_activePageId !== id){
    const prevPage = document.getElementById('page-' + _activePageId);
    if(prevPage) prevPage.classList.remove('active');
    const prevNav = document.getElementById('nav-' + _activePageId);
    if(prevNav) prevNav.classList.remove('active');
    _activePageId = id;
  }
  const newPage = document.getElementById('page-'+id);
  if(newPage) newPage.classList.add('active');
  const ni=document.getElementById('nav-'+id);
  if(ni)ni.classList.add('active');
  const titles={home:'Bontrager Positioning','learn-chapters':'Section 1 — Learn','quiz-chapters':'Section 2 — Quiz',ai:'Ask AI',settings:'Settings','about':'About','learn-subchapters':'','learn-positions':'','pos-view':'Position','quiz':'Quiz','score':'Results','dev-manager':'Developer Manager',quickreview:'⚡ Quick Review',anatomy:'Anatomy','anatomy-detail':'Anatomy Detail',book:'📖 Book','book-reader':'📖 Book'};
  document.getElementById('headerTitle').textContent=titles[id]||'Bontrager Positioning';
  // AI input bar
  document.getElementById('aiBar').className='ai-input-bar'+(id==='ai'?' show':'');
  // Auto-test AI connection on first visit to AI page
  if(id==='ai'){
    setTimeout(_refreshTokenUI, 50);
    const dot=document.getElementById('aiStatusDot');
    if(dot && !dot.dataset.tested){
      dot.dataset.tested='1';
      testAIConnection();
    }
  }
  // Build dev manager
  if(id==='dev-manager') buildDevManager();
  if(id==='book') buildBookChapterList();
  window.scrollTo(0,0);
  // refresh stats on home
  if(id==='home') updateStats();
  // Update bottom navigation active state
  _updateBottomNav(id);
}

function _updateBottomNav(id){
  const bnavMap={
    'home':'bnav-home',
    'learn-chapters':'bnav-learn','learn-subchapters':'bnav-learn','learn-positions':'bnav-learn','pos-view':'bnav-learn',
    'quiz-chapters':'bnav-quiz','quiz':'bnav-quiz','score':'bnav-quiz',
    'ai':'bnav-ai',
    'quickreview':null,'anatomy':null,'anatomy-detail':null,'book':null,'book-reader':null,'settings':null,'about':null,'dev-manager':null
  };
  // Use known IDs to avoid querySelectorAll
  ['bnav-home','bnav-learn','bnav-quiz','bnav-ai'].forEach(bid=>{
    const b=document.getElementById(bid);
    if(b) b.classList.remove('active');
  });
  const bnavId=bnavMap[id];
  if(bnavId){const el=document.getElementById(bnavId);if(el)el.classList.add('active');}
}

