// ── Hotspot Zone Editor ──────────────────────────────────────────────────────
(function(){
  var STORAGE_KEY = 'anatomy_custom_polygon_points';
  var _editorActive = false;
  var _originalPoints = {}; // regionId -> array of {polyEl, origPoints}
  var _handles = []; // {el, polyEl, ptIdx, allPts} refs for cleanup

  // One unique color per anatomical zone — shared by handles, label text, and overlay fill
  var _ZONE_COLORS = {
    head_neck:    '#e53935',
    shoulder:     '#fb8c00',
    thorax:       '#43a047',
    upper_arm:    '#1e88e5',
    forearm_hand: '#8e24aa',
    abdomen:      '#00897b',
    hip_femur:    '#d81b60',
    knee_leg:     '#6d4c41',
    foot_ankle:   '#546e7a',
    spine:        '#7b1fa2'
  };

  var _ZONE_LABELS = {
    head_neck: 'Head & Neck', shoulder: 'Shoulder', thorax: 'Thorax',
    upper_arm: 'Upper Arm', forearm_hand: 'Forearm & Hand', abdomen: 'Abdomen',
    hip_femur: 'Hip & Femur', knee_leg: 'Knee & Leg', foot_ankle: 'Foot & Ankle',
    spine: 'Spine'
  };

  // Parse "x1,y1 x2,y2 ..." into [[x1,y1],[x2,y2],...]
  function _parse(str){
    return str.trim().split(/\s+/).map(function(p){
      var c = p.split(',');
      return [parseFloat(c[0]), parseFloat(c[1])];
    });
  }

  // Serialize [[x,y],...] back to "x,y x,y ..."
  function _serialize(pts){
    return pts.map(function(p){ return p[0].toFixed(1)+','+p[1].toFixed(1); }).join(' ');
  }

  // Load saved custom points and apply to SVG polygons
  function _applyCustomPoints(){
    var raw;
    try { raw = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null'); } catch(e){ raw = null; }
    if(!raw) return;
    var svg = document.getElementById('anatomyBodySVG');
    if(!svg) return;
    svg.querySelectorAll('.skel-region[data-region]').forEach(function(g){
      var regionId = g.dataset.region;
      var saved = raw[regionId];
      if(!saved) return;
      var polygons = Array.from(g.querySelectorAll('polygon.ab-overlay'));
      saved.forEach(function(pts, idx){
        var poly = polygons[idx];
        if(poly && pts) poly.setAttribute('points', _serialize(pts));
      });
    });
  }

  // Save current SVG polygon points to localStorage
  function _saveCurrentPoints(){
    var svg = document.getElementById('anatomyBodySVG');
    if(!svg) return;
    var data = {};
    svg.querySelectorAll('.skel-region[data-region]').forEach(function(g){
      var regionId = g.dataset.region;
      var polys = Array.from(g.querySelectorAll('polygon.ab-overlay'));
      if(!polys.length) return;
      data[regionId] = polys.map(function(poly){
        return _parse(poly.getAttribute('points') || '');
      });
    });
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); } catch(e){}
  }

  // Convert SVG coordinate from a client-space event
  function _clientToSVG(svgEl, clientX, clientY){
    var rect = svgEl.getBoundingClientRect();
    var vb = svgEl.viewBox.baseVal;
    var scaleX = vb.width / rect.width;
    var scaleY = vb.height / rect.height;
    return {
      x: (clientX - rect.left) * scaleX,
      y: (clientY - rect.top) * scaleY
    };
  }

  // Color zone labels and overlays to match handle colors when editor is active
  function _applyEditorColors(){
    var mainSVG = document.getElementById('anatomyBodySVG');
    if(!mainSVG) return;
    mainSVG.querySelectorAll('.skel-region[data-region]').forEach(function(g){
      var regionId = g.dataset.region;
      var color = _ZONE_COLORS[regionId] || '#f57c00';
      g.querySelectorAll('.ab-lbl').forEach(function(txt){
        txt.setAttribute('fill', color);
      });
      g.querySelectorAll('.ab-overlay').forEach(function(poly){
        poly.setAttribute('fill', color);
        poly.setAttribute('fill-opacity', '0.18');
        poly.setAttribute('stroke', color);
        poly.setAttribute('stroke-width', '2.5');
        if(!poly.classList.contains('ab-spine-overlay')){
          poly.removeAttribute('stroke-dasharray');
        }
      });
    });
  }

  // Restore original zone label and overlay colors after editor closes
  function _removeEditorColors(){
    var mainSVG = document.getElementById('anatomyBodySVG');
    if(!mainSVG) return;
    mainSVG.querySelectorAll('.skel-region[data-region]').forEach(function(g){
      var regionId = g.dataset.region;
      g.querySelectorAll('.ab-lbl').forEach(function(txt){
        txt.setAttribute('fill', regionId === 'spine' ? 'rgba(220,160,255,1)' : 'white');
      });
      g.querySelectorAll('.ab-overlay').forEach(function(poly){
        if(poly.classList.contains('ab-spine-overlay')){
          poly.setAttribute('fill', 'rgba(160,100,210,0)');
          poly.setAttribute('stroke', 'rgba(160,100,210,0)');
          poly.setAttribute('stroke-width', '2.5');
          poly.setAttribute('stroke-dasharray', '10,6');
          poly.removeAttribute('fill-opacity');
        } else {
          poly.removeAttribute('fill');
          poly.removeAttribute('fill-opacity');
          poly.removeAttribute('stroke');
          poly.removeAttribute('stroke-width');
          poly.removeAttribute('stroke-dasharray');
        }
      });
    });
  }

  // Build color legend chips inside the editor toolbar
  function _buildLegend(){
    var legend = document.getElementById('hotspotEditorLegend');
    if(!legend) return;
    legend.innerHTML = '';
    Object.keys(_ZONE_COLORS).forEach(function(regionId){
      var color = _ZONE_COLORS[regionId];
      var chip = document.createElement('span');
      chip.style.cssText = `display:inline-flex;align-items:center;gap:4px;font-size:11px;font-weight:600;color:${color};white-space:nowrap;`;
      var dot = document.createElement('span');
      dot.style.cssText = `display:inline-block;width:10px;height:10px;border-radius:50%;background:${color};flex-shrink:0;`;
      chip.appendChild(dot);
      chip.appendChild(document.createTextNode(_ZONE_LABELS[regionId]));
      legend.appendChild(chip);
    });
  }

  // Build draggable handles for all polygon vertices
  function _buildHandles(){
    var editorSVG = document.getElementById('hotspotEditorSVG');
    var mainSVG = document.getElementById('anatomyBodySVG');
    if(!editorSVG || !mainSVG) return;

    // Clear old handles and remove previously registered SVG-level listeners
    while(editorSVG.firstChild) editorSVG.removeChild(editorSVG.firstChild);
    _handles = [];

    // Track which handle is currently being dragged
    var _activeHandle = null;

    // SVG-level move/end listeners registered once
    function _onMouseMove(e){
      if(!_activeHandle) return;
      _activeHandle.onMove(e.clientX, e.clientY);
    }
    function _onMouseEnd(){
      if(!_activeHandle) return;
      _activeHandle.onEnd();
      _activeHandle = null;
    }
    function _onTouchMove(e){
      if(!_activeHandle) return;
      e.preventDefault();
      var t = e.touches[0];
      if(t) _activeHandle.onMove(t.clientX, t.clientY);
    }
    function _onTouchEnd(){
      if(!_activeHandle) return;
      _activeHandle.onEnd();
      _activeHandle = null;
    }

    editorSVG.addEventListener('mousemove', _onMouseMove);
    editorSVG.addEventListener('mouseup', _onMouseEnd);
    editorSVG.addEventListener('mouseleave', _onMouseEnd);
    editorSVG.addEventListener('touchmove', _onTouchMove, {passive:false});
    editorSVG.addEventListener('touchend', _onTouchEnd);

    mainSVG.querySelectorAll('.skel-region[data-region]').forEach(function(g){
      var regionId = g.dataset.region;
      var color = _ZONE_COLORS[regionId] || '#f57c00';
      g.querySelectorAll('polygon.ab-overlay').forEach(function(poly){
        var pts = _parse(poly.getAttribute('points') || '');
        pts.forEach(function(pt, idx){
          var circle = document.createElementNS('http://www.w3.org/2000/svg','circle');
          circle.setAttribute('cx', pt[0]);
          circle.setAttribute('cy', pt[1]);
          circle.setAttribute('r', '22');
          circle.setAttribute('fill', color);
          circle.setAttribute('fill-opacity', '0.75');
          circle.setAttribute('stroke', '#fff');
          circle.setAttribute('stroke-width', '3');
          circle.style.cursor = 'grab';
          circle.style.touchAction = 'none';

          var handle = {
            el: circle,
            onMove: function(cx, cy){
              var sv = _clientToSVG(editorSVG, cx, cy);
              sv.x = Math.max(0, Math.min(1000, sv.x));
              sv.y = Math.max(0, Math.min(1500, sv.y));
              pts[idx] = [sv.x, sv.y];
              poly.setAttribute('points', _serialize(pts));
              circle.setAttribute('cx', sv.x);
              circle.setAttribute('cy', sv.y);
            },
            onEnd: function(){
              circle.style.cursor = 'grab';
              circle.setAttribute('r','22');
            }
          };
          _handles.push(handle);

          circle.addEventListener('mousedown', function(e){
            e.preventDefault(); e.stopPropagation();
            _activeHandle = handle;
            circle.style.cursor = 'grabbing';
            circle.setAttribute('r','28');
          });

          circle.addEventListener('touchstart', function(e){
            e.preventDefault(); e.stopPropagation();
            _activeHandle = handle;
            circle.style.cursor = 'grabbing';
            circle.setAttribute('r','28');
          }, {passive:false});

          editorSVG.appendChild(circle);
        });
      });
    });
  }

  // Snapshot current polygon points for cancel/reset
  function _snapshotPoints(){
    var mainSVG = document.getElementById('anatomyBodySVG');
    if(!mainSVG) return;
    _originalPoints = {};
    mainSVG.querySelectorAll('.skel-region[data-region]').forEach(function(g){
      var regionId = g.dataset.region;
      _originalPoints[regionId] = Array.from(g.querySelectorAll('polygon.ab-overlay')).map(function(poly){
        return poly.getAttribute('points') || '';
      });
    });
  }

  // Restore polygon points from snapshot
  function _restoreSnapshot(){
    var mainSVG = document.getElementById('anatomyBodySVG');
    if(!mainSVG) return;
    mainSVG.querySelectorAll('.skel-region[data-region]').forEach(function(g){
      var regionId = g.dataset.region;
      var saved = _originalPoints[regionId];
      if(!saved) return;
      var polys = Array.from(g.querySelectorAll('polygon.ab-overlay'));
      saved.forEach(function(pts, idx){
        if(polys[idx]) polys[idx].setAttribute('points', pts);
      });
    });
  }

  // Default polygon points — captured lazily the first time the editor is opened
  var _DEFAULTS = null;

  function _ensureDefaults(){
    if(_DEFAULTS) return;
    var mainSVG = document.getElementById('anatomyBodySVG');
    if(!mainSVG) return;
    _DEFAULTS = {};
    mainSVG.querySelectorAll('.skel-region[data-region]').forEach(function(g){
      var regionId = g.dataset.region;
      _DEFAULTS[regionId] = Array.from(g.querySelectorAll('polygon.ab-overlay')).map(function(poly){
        return poly.getAttribute('points') || '';
      });
    });
  }

  // Public API
  window._toggleHotspotEditor = function(){
    if(_editorActive){ _cancelHotspotEdits(); } else { _enterEditor(); }
  };

  function _enterEditor(){
    _editorActive = true;
    _ensureDefaults();
    _snapshotPoints();
    _buildHandles();
    _applyEditorColors();
    _buildLegend();
    var editorSVG = document.getElementById('hotspotEditorSVG');
    var bar = document.getElementById('hotspotEditorBar');
    var hint = document.getElementById('anatTapHint');
    var btn = document.getElementById('hotspotEditBtn');
    if(editorSVG) editorSVG.style.display = 'block';
    if(bar){ bar.style.display = 'flex'; }
    if(hint) hint.textContent = '✏️ Drag the colored handles to adjust zone boundaries';
    if(btn){ btn.style.background = 'var(--accent)'; btn.style.color = '#fff'; btn.style.borderColor = 'var(--accent)'; }
    // Disable region clicks on main SVG
    var mainSVG = document.getElementById('anatomyBodySVG');
    if(mainSVG){ mainSVG.style.pointerEvents = 'none'; }
  }

  function _exitEditor(){
    _editorActive = false;
    _removeEditorColors();
    var editorSVG = document.getElementById('hotspotEditorSVG');
    var bar = document.getElementById('hotspotEditorBar');
    var hint = document.getElementById('anatTapHint');
    var btn = document.getElementById('hotspotEditBtn');
    if(editorSVG) editorSVG.style.display = 'none';
    if(bar) bar.style.display = 'none';
    if(hint) hint.textContent = '🖐 Tap any region to view its anatomy';
    if(btn){ btn.style.background = ''; btn.style.color = ''; btn.style.borderColor = ''; }
    var mainSVG = document.getElementById('anatomyBodySVG');
    if(mainSVG){ mainSVG.style.pointerEvents = ''; }
    _handles = [];
  }

  window._saveHotspotEdits = function(){
    _saveCurrentPoints();
    _exitEditor();
    // Rebuild geometry after save
    _initSmartAnatomyHitTest();
  };

  window._cancelHotspotEdits = function(){
    _restoreSnapshot();
    _exitEditor();
  };

  window._resetHotspotEdits = function(){
    _ensureDefaults();
    if(!_DEFAULTS) return;
    var mainSVG = document.getElementById('anatomyBodySVG');
    if(!mainSVG) return;
    mainSVG.querySelectorAll('.skel-region[data-region]').forEach(function(g){
      var regionId = g.dataset.region;
      var defaults = _DEFAULTS[regionId];
      if(!defaults) return;
      var polys = Array.from(g.querySelectorAll('polygon.ab-overlay'));
      defaults.forEach(function(pts, idx){
        if(polys[idx]) polys[idx].setAttribute('points', pts);
      });
    });
    try { localStorage.removeItem(STORAGE_KEY); } catch(e){}
    // Rebuild handles for the reset positions
    _buildHandles();
  };

  // Apply saved custom points on load
  _applyCustomPoints();
}());

// ═══════════════════════════════════════════════════════════════════
// TRANSLATION FEATURE — Text Selection → Arabic Translation Side Panel
// ═══════════════════════════════════════════════════════════════════
(function(){
  var MAX_TRANSLATION_CHARS = 500; // MyMemory max characters per translation request
  var TRANSLATION_CACHE_KEY = 'bontrager_translation_cache_v1';
  var TRANSLATION_CACHE_LIMIT = 300;
  // Split text into tokens by whitespace and common punctuation marks.
  var WORD_SPLIT_PATTERN = /(\s+|[.,!?;:()[\]{}"'\/\\+\-]+)/;
  // Arabic text meaning: "(Offline translation - approximate)"
  var OFFLINE_TRANSLATION_SUFFIX = '\n\n(ترجمة بدون إنترنت - تقريبية)';
  var OFFLINE_PHRASE_MAP = {
    'patient seated': 'المريض في وضع الجلوس',
    'patient standing': 'المريض في وضع الوقوف',
    'patient supine': 'المريض في وضع الاستلقاء',
    'center to': 'قم بتوسيط الشعاع على',
    'directed to': 'يتم توجيهه إلى',
    'perpendicular to ir': 'عمودي على المستقبل الصوري',
    'parallel to ir': 'موازٍ للمستقبل الصوري',
    'without rotation': 'بدون دوران',
    'demonstrates': 'يُظهر',
    'this view demonstrates': 'هذه الوضعية تُظهر'
  };
  var OFFLINE_WORD_MAP = {
    patient:'المريض',
    seated:'جالس',
    standing:'واقف',
    supine:'مستلقي',
    prone:'منبطح',
    erect:'عمودي',
    hand:'اليد',
    wrist:'الرسغ',
    elbow:'المرفق',
    shoulder:'الكتف',
    humerus:'العضد',
    clavicle:'الترقوة',
    chest:'الصدر',
    abdomen:'البطن',
    pelvis:'الحوض',
    hip:'الورك',
    femur:'عظم الفخذ',
    knee:'الركبة',
    tibia:'الظنبوب',
    fibula:'الشظية',
    ankle:'الكاحل',
    foot:'القدم',
    skull:'الجمجمة',
    cervical:'عنقي',
    thoracic:'صدري',
    lumbar:'قطني',
    spine:'العمود الفقري',
    projection:'وضعية',
    ap:'أمامي-خلفي',
    pa:'خلفي-أمامي',
    lateral:'جانبي',
    oblique:'مائل',
    bilateral:'ثنائي الجانب',
    unilateral:'أحادي الجانب',
    angle:'زاوية',
    degree:'درجة',
    tube:'الأنبوب',
    cr:'الشعاع المركزي',
    sid:'مسافة المصدر إلى المستقبل',
    ir:'المستقبل الصوري',
    cassette:'الكاسيت',
    image:'صورة',
    xray:'أشعة سينية',
    'x-ray':'أشعة سينية',
    center:'توسيط',
    centered:'متمركز',
    directed:'موجه',
    rotate:'أدر',
    rotated:'مدار',
    flex:'اثنِ',
    extension:'تمديد',
    demonstrates:'يُظهر',
    shows:'يُظهر',
    without:'بدون',
    with:'مع',
    and:'و',
    or:'أو',
    to:'إلى',
    from:'من',
    right:'يمين',
    left:'يسار'
  };

  var _selText = '';
  var _popupEl = null;
  var _panelEl = null;
  var _overlayEl = null;
  var _copyBtnOriginalHTML = null;

  function _init(){
    _popupEl  = document.getElementById('selPopup');
    _panelEl  = document.getElementById('trPanel');
    _overlayEl = document.getElementById('trPanelOverlay');
    if(!_popupEl || !_panelEl) return;

    // Cache the copy button's original HTML for reset after copy feedback
    var copyBtn = document.getElementById('trCopyBtn');
    if(copyBtn) _copyBtnOriginalHTML = copyBtn.innerHTML;

    document.addEventListener('mouseup',  _onSelectionChange);
    document.addEventListener('touchend', _onSelectionChange);
    document.addEventListener('selectionchange', _onSelectionChangeLazy);
  }

  // Debounce for selectionchange (fires many times on mobile)
  var _selChangeTimer = null;
  function _onSelectionChangeLazy(){
    clearTimeout(_selChangeTimer);
    _selChangeTimer = setTimeout(function(){
      var sel = window.getSelection();
      _updateSelection(sel);
    }, 300);
  }

  function _onSelectionChange(){
    // Small delay to let the selection finalise
    setTimeout(function(){
      var sel = window.getSelection();
      _updateSelection(sel);
    }, 50);
  }

  function _updateSelection(sel){
    if(!sel || sel.isCollapsed || !sel.toString().trim()){
      _hidePopup();
      return;
    }
    var text = sel.toString().trim();
    if(text.length < 2){ _hidePopup(); return; }
    _selText = text;
    _positionPopup(sel);
  }

  function _isEmptyRect(r){
    return !r || (r.width === 0 && r.height === 0);
  }

  function _positionPopup(sel){
    if(!_popupEl) return;
    if(!sel || sel.rangeCount < 1){ _hidePopup(); return; }
    var range = sel.getRangeAt(0);
    var rect  = range.getBoundingClientRect();
    if(_isEmptyRect(rect)){
      var rects = range.getClientRects();
      if(rects && rects.length) rect = rects[0];
    }
    if(_isEmptyRect(rect)){ _hidePopup(); return; }

    _popupEl.style.display = 'flex';

    var popW = _popupEl.offsetWidth || 120;
    var popH = _popupEl.offsetHeight || 40;
    var margin = 6;

    // Prefer above the selection; fall back to below
    var top = rect.top - popH - margin;
    if(top < 4) top = rect.bottom + margin;

    var left = rect.left + rect.width / 2 - popW / 2;
    left = Math.max(6, Math.min(left, window.innerWidth - popW - 6));

    _popupEl.style.top  = top  + 'px';
    _popupEl.style.left = left + 'px';
  }

  function _hidePopup(){
    if(_popupEl) _popupEl.style.display = 'none';
  }

  function _normalizeText(text){
    return String(text || '').toLowerCase().replace(/\s+/g, ' ').trim();
  }

  function _readTranslationCache(){
    try {
      var raw = localStorage.getItem(TRANSLATION_CACHE_KEY);
      if(!raw) return { translations: {}, order: [] };
      var parsed = JSON.parse(raw);
      if(parsed && typeof parsed === 'object' && parsed.translations && typeof parsed.translations === 'object'){
        return {
          translations: parsed.translations,
          order: Array.isArray(parsed.order) ? parsed.order : Object.keys(parsed.translations)
        };
      }
      if(parsed && typeof parsed === 'object'){
        return {
          translations: parsed,
          order: Object.keys(parsed)
        };
      }
      return { translations: {}, order: [] };
    } catch(e){
      return { translations: {}, order: [] };
    }
  }

  function _saveTranslationCache(sourceText, translatedText){
    var sourceKey = _normalizeText(sourceText);
    if(!sourceKey || !translatedText) return;
    try {
      var cacheData = _readTranslationCache();
      var translations = cacheData.translations || {};
      var order = Array.isArray(cacheData.order) ? cacheData.order : [];
      if(!translations[sourceKey]){
        order.push(sourceKey);
      }
      translations[sourceKey] = translatedText;
      if(order.length > TRANSLATION_CACHE_LIMIT){
        var removeCount = order.length - TRANSLATION_CACHE_LIMIT;
        var evictedKeys = order.splice(0, removeCount);
        evictedKeys.forEach(function(evicted){
          if(evicted) delete translations[evicted];
        });
      }
      localStorage.setItem(TRANSLATION_CACHE_KEY, JSON.stringify({
        translations: translations,
        order: order
      }));
    } catch(e){}
  }

  function _getCachedTranslation(sourceText){
    var key = _normalizeText(sourceText);
    if(!key) return '';
    var cacheData = _readTranslationCache();
    return (cacheData.translations && cacheData.translations[key]) || '';
  }

  function _translateOffline(sourceText){
    var text = String(sourceText || '').trim();
    if(!text) return '';
    var normalized = _normalizeText(text);
    if(OFFLINE_PHRASE_MAP[normalized]){
      return OFFLINE_PHRASE_MAP[normalized];
    }
    var translatedAny = false;
    var parts = text.split(WORD_SPLIT_PATTERN);
    var out = parts.map(function(part){
      var n = _normalizeText(part);
      if(!n) return part;
      if(OFFLINE_WORD_MAP[n]){
        translatedAny = true;
        return OFFLINE_WORD_MAP[n];
      }
      return part;
    }).join('');
    if(!translatedAny) return '';
    return out + OFFLINE_TRANSLATION_SUFFIX;
  }

  // Public: called by the Translate button in the popup
  window.openTranslationPanel = function(){
    if(!_selText) return;
    _hidePopup();

    var origEl   = document.getElementById('trOriginalText');
    var resultEl = document.getElementById('trResultText');
    var loadEl   = document.getElementById('trLoading');
    var errEl    = document.getElementById('trError');
    var copyBtn  = document.getElementById('trCopyBtn');

    if(origEl)   origEl.textContent = _selText;
    if(resultEl){ resultEl.textContent = ''; resultEl.style.display = 'none'; }
    if(loadEl)   loadEl.style.display  = 'flex';
    if(errEl)    errEl.style.display   = 'none';
    if(copyBtn)  copyBtn.style.display = 'none';

    _panelEl.classList.add('open');
    _overlayEl.classList.add('open');

    _fetchTranslation(_selText, function(err, translated){
      if(loadEl) loadEl.style.display = 'none';
      if(err){
        if(errEl){
          var msgEl = document.getElementById('trErrorMsg');
          if(msgEl) msgEl.textContent = err;
          errEl.style.display = 'flex';
        }
      } else {
        if(resultEl){
          resultEl.textContent = translated;
          resultEl.style.display = 'block';
        }
        if(copyBtn) copyBtn.style.display = 'inline-flex';
      }
    });
  };

  window.closeTranslationPanel = function(){
    if(_panelEl)  _panelEl.classList.remove('open');
    if(_overlayEl) _overlayEl.classList.remove('open');
  };

  window.copyTranslation = function(){
    var resultEl = document.getElementById('trResultText');
    if(!resultEl || !resultEl.textContent) return;
    var btn = document.getElementById('trCopyBtn');
    try {
      navigator.clipboard.writeText(resultEl.textContent).then(function(){
        if(btn){ btn.classList.add('copied'); btn.textContent = '✓ تم النسخ'; }
        setTimeout(function(){
          if(btn){
            btn.classList.remove('copied');
            if(_copyBtnOriginalHTML) btn.innerHTML = _copyBtnOriginalHTML;
          }
        }, 2000);
      });
    } catch(e){}
  };

  function _fetchTranslation(text, cb){
    // Use MyMemory free translation API (no key needed, 1000 words/day free)
    var sourceText = String(text || '').substring(0, MAX_TRANSLATION_CHARS);
    var cached = _getCachedTranslation(sourceText);
    if(cached){
      cb(null, cached);
      return;
    }

    // Best-effort offline hint; fetch catch path below is the final fallback.
    if(typeof navigator !== 'undefined' && navigator.onLine === false){
      var offlineOnlyResult = _translateOffline(sourceText);
      if(offlineOnlyResult){
        cb(null, offlineOnlyResult);
      } else {
        cb('أنت غير متصل بالإنترنت ولا توجد ترجمة محفوظة لهذا النص');
      }
      return;
    }

    var url = 'https://api.mymemory.translated.net/get?q=' +
              encodeURIComponent(sourceText) +
              '&langpair=en%7Car';
    var canTimeoutSignal = (typeof AbortSignal !== 'undefined' && typeof AbortSignal.timeout === 'function');
    var hasAbortController = (typeof AbortController !== 'undefined');
    var timeoutMs = 10000;
    var timer = null;
    var controller = null;
    var signal = undefined;

    if(canTimeoutSignal){
      signal = AbortSignal.timeout(timeoutMs);
    } else if(hasAbortController){
      controller = new AbortController();
      signal = controller.signal;
      timer = setTimeout(function(){
        controller.abort();
      }, timeoutMs);
    }

    fetch(url, { signal: signal })
      .then(function(res){
        if(!res.ok) throw new Error('HTTP ' + res.status);
        return res.json();
      })
      .then(function(data){
        if(timer) clearTimeout(timer);
        if(data && data.responseData && data.responseData.translatedText){
          _saveTranslationCache(sourceText, data.responseData.translatedText);
          cb(null, data.responseData.translatedText);
        } else {
          var offlineFallback = _translateOffline(sourceText);
          if(offlineFallback){
            cb(null, offlineFallback);
          } else {
            cb('لم يتم استلام الترجمة');
          }
        }
      })
      .catch(function(err){
        if(timer) clearTimeout(timer);
        var fallback = _translateOffline(sourceText);
        if(fallback){
          cb(null, fallback);
          return;
        }
        if(err && err.name === 'AbortError'){
          cb('انتهت مهلة الاتصال، حاول مرة أخرى أو استخدم الترجمة بدون إنترنت لنصوص أقصر');
        } else {
          cb('تعذّر الاتصال بخدمة الترجمة ولا توجد ترجمة محلية مطابقة');
        }
      });
  }

  // Initialise after DOM is ready
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', _init);
  } else {
    _init();
  }
}());
